<?php
/**
 * Tillpress admin skin: the shared card and pill styling on this plugin's own admin screens.
 * Generated by tools/skin/sync.php from tools/skin/tp-skin.css; change it there, not here.
 *
 * @package OrderBayLite
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Adds the skin body classes and stylesheet on this plugin's screens only.
 */
class OBLT_Skin {

	/** Admin page slugs that start with one of these get the skin. */
	const PAGE_PREFIXES = array( 'orderbay-lite', 'oblt-' );

	/** Page slugs that start with one of these do not (another plugin's pages). */
	const PAGE_EXCLUDE = array();

	/** Post types whose list and edit screens get the skin. */
	const POST_TYPES = array();

	/**
	 * Hook in once.
	 */
	public static function init() {
		static $done = false;
		if ( $done ) {
			return;
		}
		$done = true;
		add_filter( 'admin_body_class', array( __CLASS__, 'body_class' ) );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'enqueue' ), 20 );
	}

	/**
	 * Whether an admin page slug belongs to this plugin (pure).
	 *
	 * @param string $page Page slug.
	 * @return bool
	 */
	public static function page_matches( $page ) {
		$page = (string) $page;
		if ( '' === $page ) {
			return false;
		}
		foreach ( self::PAGE_EXCLUDE as $no ) {
			if ( 0 === strpos( $page, $no ) ) {
				return false;
			}
		}
		foreach ( self::PAGE_PREFIXES as $yes ) {
			if ( 0 === strpos( $page, $yes ) ) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether the current admin screen is one of ours.
	 *
	 * @return bool
	 */
	public static function is_screen() {
		$page = isset( $_GET['page'] ) ? sanitize_key( wp_unslash( $_GET['page'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Read-only screen check.
		if ( '' !== $page ) {
			return self::page_matches( $page );
		}
		if ( ! self::POST_TYPES || ! function_exists( 'get_current_screen' ) ) {
			return false;
		}
		$screen = get_current_screen();
		return $screen && in_array( $screen->post_type, self::POST_TYPES, true ) && in_array( $screen->base, array( 'edit', 'post' ), true );
	}

	/**
	 * Body classes.
	 *
	 * @param string $classes Existing classes.
	 * @return string
	 */
	public static function body_class( $classes ) {
		return self::is_screen() ? $classes . ' tp-skin tp-skin--orderbay ' : $classes;
	}

	/**
	 * Stylesheet.
	 */
	public static function enqueue() {
		if ( self::is_screen() ) {
			wp_enqueue_style( 'oblt-tp-skin', OBLT_PLUGIN_URL . 'assets/tp-skin.css', array(), OBLT_VERSION );
		}
	}
}
